head.b:skin:
/*
 * Name: Rumah Hunian Berkelas Elit
 * Version: V10.0-PRO (Omni-Engine)
 * Signature: @circlemonth / Heaven
 * Theme: Cyber-Tech Neon Glow Real Estate
 */

:root {
    --neon-blue: #00f3ff;
    --neon-purple: #bc13fe;
    --bg-dark: #050505;
    --card-bg: rgba(20, 20, 20, 0.8);
    --glass: rgba(255, 255, 255, 0.05);
    --font-main: 'Inter', sans-serif;
}

body {
    background-color: var(--bg-dark);
    color: #ffffff;
    font-family: var(--font-main);
    margin: 0;
    overflow-x: hidden;
}

/* --- CORE ARCHITECTURE: CSS GRID --- */
.main-wrapper {
    display: grid;
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr auto;
    min-height: 100vh;
}

/* --- HERO HEADER: CYBER-TECH GLOW --- */
.hero-header {
    height: 80vh;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1920&q=80');
    background-size: cover;
    background-position: center;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    border-bottom: 2px solid var(--neon-blue);
    box-shadow: 0 0 20px var(--neon-blue);
    position: relative;
    overflow: hidden;
}

.hero-header::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: repeating-linear-gradient(0deg, rgba(0,0,0,0.1) 0px, rgba(0,0,0,0.1) 1px, transparent 1px, transparent 2px);
    pointer-events: none;
}

.hero-title {
    font-size: 4rem;
    text-transform: uppercase;
    text-shadow: 0 0 10px var(--neon-blue), 0 0 20px var(--neon-purple);
    animation: pulse 2s infinite;
}

/* --- CONTENT FILTERING SECTION --- */
.filter-bar {
    display: flex;
    justify-content: center;
    gap: 15px;
    padding: 20px;
    background: var(--glass);
    backdrop-filter: blur(10px);
}

.filter-btn {
    padding: 10px 20px;
    border: 1px solid var(--neon-purple);
    background: transparent;
    color: white;
    cursor: pointer;
    transition: 0.3s;
}

.filter-btn:hover {
    background: var(--neon-purple);
    box-shadow: 0 0 15px var(--neon-purple);
}

/* --- GRID POSTS --- */
.post-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 25px;
    padding: 40px;
}

.post-card {
    background: var(--card-bg);
    border: 1px solid rgba(0, 243, 255, 0.3);
    padding: 15px;
    transition: transform 0.3s ease;
}

.post-card:hover {
    transform: translateY(-10px);
    border-color: var(--neon-blue);
}

/* --- SIGNATURE FOOTER --- */
footer {
    padding: 40px;
    text-align: center;
    border-top: 1px solid var(--neon-purple);
    font-size: 0.8rem;
    letter-spacing: 2px;
}

@keyframes pulse {
    0% { opacity: 1; }
    50% { opacity: 0.8; }
    100% { opacity: 1; }
}

/* Mobile First */
@media (max-width: 768px) {
    .hero-title { font-size: 2rem; }
    .post-grid { padding: 15px; }
}
